def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: The number of nanoseconds since midnight.
    :param tz: An optional timezone to localize the time.
    :return: A datetime.time or datetime.datetime object based on the presence of tz.
    """
    from datetime import datetime, time, timedelta, timezone

    if not isinstance(nanoseconds, int) or nanoseconds < 0:
        raise ValueError("Nanoseconds must be a non-negative integer.")

    if tz is not None and not isinstance(tz, (timezone, str)):
        raise ValueError("Timezone must be a datetime.timezone object or a string.")

    seconds, nano_remainder = divmod(nanoseconds, 1_000_000_000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)

    if hours >= 24:
        raise ValueError("Nanoseconds exceed the number of nanoseconds in a day.")

    if tz is None:
        return time(hour=hours, minute=minutes, second=seconds, microsecond=nano_remainder // 1000)
    else:
        if isinstance(tz, str):
            try:
                tz = timezone(timedelta(seconds=int(tz)))
            except ValueError:
                raise ValueError("Timezone string must represent seconds offset.")
        dt = datetime.combine(datetime.min, time(hour=hours, minute=minutes, second=seconds, microsecond=nano_remainder // 1000))
        return dt.astimezone(tz).time()

