def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor, as_completed

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    if not cmd:
        raise ValueError("cmd cannot be empty")

    if _max_length <= 0:
        raise ValueError("_max_length must be greater than 0")

    def run_command(args: list[str]) -> subprocess.CompletedProcess:
        full_cmd = list(cmd) + args
        return subprocess.run(full_cmd, capture_output=True)

    def split_args(args: Sequence[str], max_length: int) -> list[list[str]]:
        parts = []
        current_part = []
        current_length = len(' '.join(cmd)) + len(os.sep)  # Base command length

        for arg in args:
            arg_length = len(arg) + 1  # Add 1 for the space after the argument
            if current_length + arg_length > max_length:
                parts.append(current_part)
                current_part = []
                current_length = len(' '.join(cmd)) + len(os.sep)
            current_part.append(arg)
            current_length += arg_length

        if current_part:
            parts.append(current_part)

        return parts

    all_args = split_args(varargs, _max_length)
    exit_code = 0
    output = bytearray()

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = {executor.submit(run_command, args): args for args in all_args}

        for future in as_completed(futures):
            try:
                result = future.result()
                output.extend(result.stdout)
                if result.returncode != 0:
                    exit_code = result.returncode  # Keep the last non-zero exit code
            except Exception as e:
                exit_code = 1
                output.extend(f"An error occurred: {e}\n".encode())

    return exit_code, bytes(output)

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor
    from itertools import islice

    if not cmd:
        raise ValueError("Command cannot be empty.")
    if target_concurrency <= 0:
        raise ValueError("Target concurrency must be a positive integer.")
    if _max_length <= 0:
        raise ValueError("Max length must be a positive integer.")

    def _get_platform_max_length():
        # Placeholder for actual platform-specific length retrieval
        return 4096  # Example value

    def _chunked(iterator, n):
        """Yield successive n-sized chunks from iterator."""
        it = iter(iterator)
        while True:
            chunk = list(islice(it, n))
            if not chunk:
                return
            yield chunk

    def _run_command(args):
        try:
            result = subprocess.run(
                list(cmd) + args,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                check=True,
                text=False,
                **kwargs
            )
            return (result.returncode, result.stdout)
        except subprocess.CalledProcessError as e:
            return (e.returncode, e.stdout)

    try:
        chunk_size = max(_max_length // sum(map(len, cmd)) - 1, 1)
        chunks = _chunked(varargs, chunk_size)

        with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            results = list(executor.map(_run_command, chunks))

        # Assuming we want to return the last chunk's result
        return results[-1] if results else (0, b'')

    except Exception as e:
        return (1, str(e).encode())

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import os
    import subprocess
    import shlex
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from itertools import islice

    def _chunked(it, size):
        it = iter(it)
        return iter(lambda: tuple(islice(it, size)), ())

    def _run_command(command):
        try:
            process = subprocess.run(
                command,
                check=True,
                capture_output=True,
                text=False,
                shell=False,
            )
            return process.returncode, process.stdout
        except subprocess.CalledProcessError as e:
            return e.returncode, e.stdout

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    command_template = ' '.join(map(shlex.quote, cmd)) + ' {}'
    arg_length = sum(len(arg) for arg in varargs) + len(varargs) * 2  # Add space between args

    if arg_length > _max_length:
        chunk_size = 1
        while arg_length > _max_length and chunk_size < len(varargs):
            chunk_size += 1
            arg_length = sum(len(arg) + 2 for arg in varargs[::chunk_size])  # Approximation

        if arg_length > _max_length:
            raise ValueError("Command length exceeds maximum length even when chunked")

        commands = [
            _run_command(command_template.format(' '.join(map(shlex.quote, chunk))))
            for chunk in _chunked(varargs, chunk_size)
        ]
    else:
        commands = [_run_command(command_template.format(' '.join(map(shlex.quote, varargs))))]

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_command = {executor.submit(_run_command, cmd): cmd for cmd in commands}
        results = []
        for future in as_completed(future_to_command):
            results.append(future.result())

    returncode = 0
    stdout = b''
    for rc, out in results:
        returncode = returncode or rc
        stdout += out

    return returncode, stdout

def _shuffled(seq: Sequence[str]) -> list[str]:
