def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not cmd:
        raise ValueError("Command tuple cannot be empty")

    try:
        # Check if the first element is a script with a shebang
        import os
        import subprocess

        script_path = cmd[0]
        if os.name == 'nt' and os.path.isfile(script_path):
            with open(script_path, 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    # Assume the shebang line points to an interpreter
                    # For Windows, we need to replace it with the actual interpreter path
                    interpreter = first_line[2:].split()[0]
                    if interpreter.lower() == '/usr/bin/env':
                        # Handle env shebangs by guessing the interpreter
                        interpreter = subprocess.check_output(['where', 'python']).decode().strip().split('\r\n')[0]
                    # Replace the script path with the interpreter and script path
                    cmd = (interpreter, script_path) + cmd[1:]

        return cmd

    except Exception as e:
        raise RuntimeError(f"Failed to normalize command: {e}")

