    all_items = set(item for ordering in orderings for item in ordering)
    incoming_edges = {node: 0 for node in all_items}
    for node, children in graph.items():
        for child in children:
            incoming_edges[child] += 1

    start_nodes = [node for node, count in incoming_edges.items() if count == 0]

    # Perform a topological sort
    merged_ordering = []
    visited = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        if node in graph:
            for neighbor in graph[node]:
                dfs(neighbor)
        merged_ordering.append(node)

    for start_node in start_nodes:
        dfs(start_node)

    # Reverse the result to get the correct ordering
    merged_ordering.reverse()

    # Check if all items are included in the merged ordering
    if len(merged_ordering) != len(all_items):
        raise ValueError("Cycle detected or incomplete ordering")

