def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of
		the in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
		contains the set of in-style parameters. It maps each parameter
		(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
		is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
		If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
		*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
		"""
		try:
			if isinstance(params, (dict, collections.Mapping)):
				out_params = {f'p{idx}': value for idx, value in enumerate(params.values())}
				formatted_sql = sql
				for key, new_key in zip(params.keys(), out_params.keys()):
					placeholders = [f'%({key})', f':{key}', f'@{key}', f'${key}', f'?']
					for placeholder in placeholders:
						formatted_sql = formatted_sql.replace(placeholder, f'%({new_key})s')
				return formatted_sql, list(out_params.values())

			elif isinstance(params, (list, collections.Sequence)):
				out_params = [f'p{idx}' for idx in range(len(params))]
				formatted_sql = sql
				for idx, param in enumerate(params):
					placeholders = [f'%s', f'?', f'$({idx+1})', f':{idx+1}', f'@{idx+1}']
					for placeholder in placeholders:
						formatted_sql = formatted_sql.replace(placeholder, f'%({out_params[idx]})s')
				return formatted_sql, list(out_params)

			else:
				raise ValueError("params must be a Mapping or Sequence")

		except Exception as e:
			raise ValueError(f"Error formatting SQL: {str(e)}")

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    try:
        if not isinstance(sql, (str, bytes)):
            raise ValueError("sql must be a string or bytes")

        if not isinstance(many_params, Iterable):
            raise ValueError("many_params must be an Iterable")

        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style

        if in_style == 'named' and out_style == 'ordinal':
            def convert_params(params):
                if not isinstance(params, Mapping):
                    raise ValueError("Each parameter set must be a Mapping for named in-style parameters")
                return list(params.values())

        elif in_style == 'ordinal' and out_style == 'named':
            def convert_params(params):
                if not isinstance(params, Sequence):
                    raise ValueError("Each parameter set must be a Sequence for ordinal in-style parameters")
                return dict(zip(self.SQLParams.param_names, params))

        elif in_style == out_style:
            def convert_params(params):
                return params

        else:
            raise ValueError("Unsupported parameter style conversion")

        formatted_sql = sql
        converted_params = [convert_params(params) for params in many_params]

        return formatted_sql, converted_params

    except Exception as e:
        raise RuntimeError(f"Error formatting SQL query: {e}")

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		if not isinstance(sql, (str, bytes)):
			raise ValueError("SQL query must be a string or bytes.")

		if not isinstance(many_params, Iterable):
			raise ValueError("many_params must be an iterable.")

		in_style = self.SQLParams.in_style
		out_style = self.SQLParams.out_style

		if in_style == out_style:
			return sql, list(many_params)

		# Determine if we are dealing with named or positional parameters
		is_named = isinstance(next(iter(many_params), {}), Mapping)

		if in_style == 'named' and out_style == 'pyformat':
			# Convert named params to pyformat
			param_map = {name: f"%({name})s" for name in many_params[0].keys()}
			formatted_sql = re.sub(r":([a-zA-Z_][a-zA-Z0-9_]*)", lambda m: param_map[m.group(1)], sql)
			converted_params = many_params

		elif in_style == 'pyformat' and out_style == 'named':
			# Convert pyformat to named params
			named_params = re.findall(r"%\((\w+)\)s", sql)
			if len(named_params) != len(many_params[0]):
				raise ValueError("Number of named parameters in SQL does not match number of parameters in params.")
			param_map = {name: f":{name}" for name in named_params}
			formatted_sql = re.sub(r"%\((\w+)\)s", lambda m: param_map[m.group(1)], sql)
			converted_params = many_params

		elif in_style == 'qmark' and out_style == 'named':
			# Convert qmark to named params
			if is_named:
				raise ValueError("Cannot convert qmark style to named parameters with a mapping.")
			named_params = {i: f":param{i+1}" for i in range(len(many_params[0]))}
			formatted_sql = re.sub(r"\?", lambda _, i=iter(named_params.keys()): named_params[next(i)], sql)
			converted_params = many_params

		else:
			raise NotImplementedError(f"Conversion from {in_style} to {out_style} is not supported.")

		return formatted_sql, converted_params

