    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    spec_version = self.spec_version
    if extract_spec_version:
        try:
            type_value = inventory.get('type')
            if type_value == 'type1':
                spec_version = '1.0'
            elif type_value == 'type2':
                spec_version = '2.0'
            # Add more type to version mappings as necessary
        except Exception as e:
            # Log the exception if needed, but continue with the current spec_version
            pass

    # Perform validation based on the spec_version
    if spec_version == '1.0':
        # Validation logic for version 1.0
        if 'required_field_v1' not in inventory:
            raise ValueError("Missing required field 'required_field_v1' for version 1.0")
    elif spec_version == '2.0':
        # Validation logic for version 2.0
        if 'required_field_v2' not in inventory:
            raise ValueError("Missing required field 'required_field_v2' for version 2.0")
    else:
        raise ValueError(f"Unsupported spec version: {spec_version}")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    if not isinstance(manifest_files, dict) or not isinstance(digests_used, set):
        raise ValueError("manifest_files must be a dictionary and digests_used must be a set")

    all_manifest_digests = set()
    for file_data in manifest_files.values():
        if not isinstance(file_data, dict) or 'digest' not in file_data:
            raise ValueError("Each manifest entry must be a dictionary containing a 'digest' key")
        all_manifest_digests.add(file_data['digest'])

    missing_digests = all_manifest_digests - digests_used
    unused_digests = digests_used - all_manifest_digests

    return {
        'all_digests_present': not missing_digests,
        'all_digests_used': not unused_digests,
        'missing_digests': list(missing_digests),
        'unused_digests': list(unused_digests)
    }

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, list) or not isinstance(digests_used, list):
        raise ValueError("Both manifest_files and digests_used should be lists.")

    manifest_digests = set()
    for manifest in manifest_files:
        if not isinstance(manifest, dict):
            raise ValueError("Each manifest file should be a dictionary.")
        manifest_digests.update(manifest.get('digests', []))

    if not manifest_digests:
        raise ValueError("No digests found in the provided manifest files.")

    for digest in digests_used:
        if not isinstance(digest, str):
            raise ValueError("Each digest in digests_used should be a string.")
        if digest not in manifest_digests:
            raise ValueError(f"Digest {digest} is used but not present in the manifest files.")

    unused_digests = manifest_digests - set(digests_used)
    if unused_digests:
        raise ValueError(f"Digests present in manifest but not used: {unused_digests}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    if not isinstance(manifest_files, (list, dict)) or not isinstance(digests_used, set):
        raise ValueError("Invalid input types: manifest_files should be a list or dict, and digests_used should be a set.")

    digests_present = set()

    if isinstance(manifest_files, list):
        for entry in manifest_files:
            if not isinstance(entry, dict) or 'digest' not in entry:
                raise ValueError("Each entry in manifest_files list should be a dict with a 'digest' key.")
            digests_present.add(entry['digest'])
    elif isinstance(manifest_files, dict):
        for key, value in manifest_files.items():
            if not isinstance(value, dict) or 'digest' not in value:
                raise ValueError("Each value in manifest_files dict should be a dict with a 'digest' key.")
            digests_present.add(value['digest'])

    missing_digests = digests_used - digests_present
    if missing_digests:
        raise KeyError(f"Digests used but not present in manifest: {missing_digests}")

    unused_digests = digests_present - digests_used
    if unused_digests:
        raise KeyError(f"Digests present in manifest but not used: {unused_digests}")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
