def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    try:
        if not isinstance(xmls, list) or not isinstance(files, list):
            raise ValueError("xmls and files should be lists.")

        grouped_files = {}
        xml Basinames = {os.path.splitext(os.path.basename(xml))[0] for xml in xmls}

        for file in files:
            file_basename = os.path.splitext(os.path.basename(file))[0]
            for xml_basename in xml_basenames:
                if file_basename.startswith(xml_basename):
                    if xml_basename not in grouped_files:
                        grouped_files[xml_basename] = []
                    grouped_files[xml_basename].append(file)
                    break

        return {xml_basename: Package(files) for xml_basename, files in grouped_files.items()}

    except Exception as e:
        return {"error": str(e)}

