def _explore_folder(folder):
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not os.path.isdir(folder):
        raise ValueError(f"The provided path {folder} is not a valid directory.")

    package_data = defaultdict(list)

    try:
        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                file_path = os.path.join(folder, filename)
                tree = ET.parse(file_path)
                root = tree.getroot()
                basename = os.path.splitext(filename)[0]
                package_data[basename].append({'file': filename, 'root': root})
    except ET.ParseError as e:
        raise ValueError(f"Error parsing XML file in {folder}: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

    return dict(package_data)

def _explore_folder(folder):
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str):
        raise ValueError("Folder must be a string")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The folder {folder} does not exist")

    data = defaultdict(list)

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    base_name = os.path.splitext(file)[0]
                    data[base_name].append(ET.tostring(root_element, encoding='unicode'))
                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}")
                except Exception as e:
                    print(f"Warning: An error occurred while processing {file_path}: {e}")

    return dict(data)

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise ValueError("The folder parameter must be a string.")

    if not os.path.exists(folder):
        raise FileNotFoundError(f"The folder '{folder}' does not exist.")

    if not os.path.isdir(folder):
        raise NotADirectoryError(f"The path '{folder}' is not a directory.")

    result = {}

    for filename in os.listdir(folder):
        if filename.endswith('.xml'):
            base_name = os.path.splitext(filename)[0]
            if base_name not in result:
                result[base_name] = []
            file_path = os.path.join(folder, filename)
            try:
                with open(file_path, 'r', encoding='utf-8') as file:
                    content = file.read()
                    result[base_name].append(content)
            except IOError as e:
                print(f"Error reading file {file_path}: {e}")

    return result

def _explore_folder(folder):
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str) or not os.path.isdir(folder):
        raise ValueError("Provided folder is not a valid directory path.")

    package_data = defaultdict(list)

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    base_name = os.path.splitext(file)[0]
                    package_data[base_name].append({
                        'file': file,
                        'path': file_path,
                        'root_element': root_element.tag,
                        'namespace': root_element.tag.split('}', 1)[0].strip('{') if '}' in root_element.tag else None
                    })
                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}. Skipping.")
                except Exception as e:
                    print(f"An error occurred while processing file {file_path}: {e}")

    return dict(package_data)

def _explore_folder(folder):
