    if not isinstance(folder, str):
        raise ValueError("The folder parameter must be a string.")
    if not os.path.isdir(folder):
        raise ValueError("The provided folder does not exist or is not a directory.")

    package_data = {}

    for root, dirs, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                base_name = os.path.basename(os.path.splitext(file)[0])
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    if base_name not in package_data:
                        package_data[base_name] = []
                    package_data[base_name].append(ET.tostring(root_element, encoding='unicode'))
                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}. Skipping this file.")
                except Exception as e:
                    print(f"An error occurred while processing {file_path}: {e}")

    return package_data

def add_rendition(self, lang, file_path):
    if not isinstance(lang, str) or not isinstance(file_path, str):
        raise ValueError("Both lang and file_path must be strings.")
    if not lang or not file_path:
        raise ValueError("Both lang and file_path must be non-empty strings.")

    if not hasattr(self, 'renditions'):
