def pretty(self, indent=0, debug=False):
    try:
        indent_str = '  ' * indent
        result = f"{indent_str}<{self.__class__.__name__}>\n"
        for attr, value in self.__dict__.items():
            if isinstance(value, (list, tuple, set)):
                result += f"{indent_str}  {attr}: [\n"
                for item in value:
                    if hasattr(item, 'pretty'):
                        result += item.pretty(indent + 2, debug) + ",\n"
                    else:
                        result += f"{indent_str}    {item},\n"
                result += f"{indent_str}  ]\n"
            elif isinstance(value, dict):
                result += f"{indent_str}  {attr}: {{\n"
                for key, val in value.items():
                    result += f"{indent_str}    {key}: "
                    if hasattr(val, 'pretty'):
                        result += val.pretty(indent + 2, debug) + ",\n"
                    else:
                        result += f"{val},\n"
                result += f"{indent_str}  }}\n"
            elif hasattr(value, 'pretty'):
                result += f"{indent_str}  {attr}: {value.pretty(indent + 2, debug)}\n"
            else:
                result += f"{indent_str}  {attr}: {value}\n"
        if debug:
            result += f"{indent_str}  id: {id(self)}\n"
        result += f"{indent_str}</{self.__class__.__name__}>\n"
        return result
    except Exception as e:
        return f"{indent_str}<ERROR: {str(e)}>\n"

