def absorb(self, args):
    def apply_absorption(expr):
        try:
            a, op, b = expr
            if op == '&':
                if b.startswith(f'~{a}'):
                    return f'{a} & {b[2:-1]}'
                elif b.startswith(f'{a} |'):
                    return a
            elif op == '|':
                if b.startswith(f'~{a}'):
                    return f'{a} | {b[2:-1]}'
                elif b.startswith(f'{a} &'):
                    return a
            return expr
        except (ValueError, TypeError):
            return expr

    if not isinstance(args, list):
        raise ValueError("Input must be a list of expressions")

    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3:
            result.append(apply_absorption(expr))
        else:
            result.append(expr)
    return result

def on(self, hook):
    def decorator(func):
        if not callable(func):
            raise ValueError("The handler must be a callable function.")
        if hook not in self.registry:
            self.registry[hook] = []
        self.registry[hook].append(func)
        return func
    return decorator

