def _fromutc(self, dt):
    if dt is None or not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")

    try:
        # Convert the given UTC time to the current timezone
        new_dt = dt.astimezone(self)
    except Exception as e:
        raise RuntimeError(f"Error converting datetime to timezone: {e}")

    # Check if the datetime is ambiguous
    if self.localize(new_dt.replace(tzinfo=None)).dst() != self.utcoffset(new_dt):
        # If the UTC offset does not match, it is the first occurrence of the ambiguous time
        return new_dt
    else:
        # Otherwise, it is the second occurrence of the ambiguous time
        return new_dt + self.utcoffset(new_dt) - self.utcoffset(new_dt - timedelta(hours=1))

def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("Input must be a timezone-aware datetime object.")

    # Calculate the equivalent time in the new timezone
    new_dt = self.localize(dt.replace(tzinfo=None), is_dst=None)

    # Check for ambiguous times and determine the fold
    if self.localize(dt.replace(tzinfo=None), is_dst=True) == self.localize(dt.replace(tzinfo=None), is_dst=False):
        # If the time is ambiguous, determine the fold
        if new_dt.utcoffset() == self.localize(dt.replace(tzinfo=None), is_dst=True).utcoffset():
            new_dt = new_dt.replace(fold=1)
        else:
            new_dt = new_dt.replace(fold=0)

    return new_dt

