    good_objects = 0

    try:
        # Assuming self.storage_root is the root of the hierarchy to be validated
        for obj in self.storage_root.iterate_objects():
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
