def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value, merged_dict):
        if key in merged_dict:
            existing_value = merged_dict[key]
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                existing_value.value = deep_merge_nodes(existing_value.value + value.value)
            else:
                merged_dict[key] = value
        else:
            merged_dict[key] = value

    merged_dict = defaultdict(list)
    for key_node, value_node in nodes:
        key = key_node.value
        merge_values(key, value_node, merged_dict)

    return [(ruamel.yaml.nodes.ScalarNode(tag=key_node.tag, value=key), value) for key, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value1, value2):
        if isinstance(value1, list) and isinstance(value2, list):
            merged_value = defaultdict(list)
            for k, v in value1 + value2:
                if isinstance(v, list):
                    merged_value[k].extend(v)
                else:
                    merged_value[k].append(v)
            return [(k, v[0] if len(v) == 1 else merge_values(k, v[0], v[1])) for k, v in merged_value.items()]
        elif isinstance(value1, list) and not isinstance(value2, list):
            return merge_values(key, value1, [value2])
        elif not isinstance(value1, list) and isinstance(value2, list):
            return merge_values(key, [value1], value2)
        else:
            return value2

    merged_dict = defaultdict(list)
    for key_node, value_node in nodes:
        key = key_node.value
        merged_dict[key].append(value_node)

    result = []
    for key_node, value_nodes in merged_dict.items():
        if len(value_nodes) == 1:
            result.append((key_node, value_nodes[0]))
        else:
            merged_value = value_nodes[0]
            for value_node in value_nodes[1:]:
                merged_value = merge_values(key_node, merged_value, value_node)
            result.append((key_node, merged_value))

    return result

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(key, value, merged_dict):
        if isinstance(value, MappingNode):
            if key not in merged_dict:
                merged_dict[key] = value
            else:
                if not isinstance(merged_dict[key], MappingNode):
                    raise ValueError(f"Collision at key {key}: expected MappingNode, got {type(merged_dict[key])}")
                merged_value_dict = dict(merged_dict[key].value)
                value_dict = dict(value.value)
                for sub_key, sub_value in value_dict.items():
                    merge_values(sub_key, sub_value, merged_value_dict)
                merged_dict[key].value = list(merged_value_dict.items())
        else:
            merged_dict[key] = value

    merged_dict = {}
    for key, value in nodes:
        if not isinstance(key, ScalarNode):
            raise ValueError(f"Expected ScalarNode as key, got {type(key)}")
        merge_values(key, value, merged_dict)

    return [(key, value) for key, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def merge_values(value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            merged_value = value1.value[:]
            value1_keys = {item[0].value for item in value1.value}
            for key, val in value2.value:
                if key.value in value1_keys:
                    for i, (k, v) in enumerate(merged_value):
                        if k.value == key.value:
                            merged_value[i] = (k, merge_values(v, val))
                else:
                    merged_value.append((key, val))
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            return value2

    merged_dict = {}
    for key, value in nodes:
        if key.value in merged_dict:
            merged_dict[key.value] = merge_values(merged_dict[key.value], value)
        else:
            merged_dict[key.value] = value

    return [(ScalarNode(tag=key.tag, value=key_value), value) for key_value, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, new_value, existing_value):
        if isinstance(new_value, ruamel.yaml.nodes.MappingNode) and isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
            existing_dict = dict(existing_value.value)
            new_dict = dict(new_value.value)
            for k, v in new_dict.items():
                if k in existing_dict:
                    existing_dict[k] = merge_values(k, v, existing_dict[k])
                else:
                    existing_dict[k] = v
            return ruamel.yaml.nodes.MappingNode(tag=new_value.tag, value=list(existing_dict.items()))
        else:
            return new_value

    merged_dict = defaultdict(lambda: None)
    for key_node, value_node in nodes:
        key = key_node.value
        if merged_dict[key] is None:
            merged_dict[key] = (key_node, value_node)
        else:
            _, existing_value_node = merged_dict[key]
            merged_value_node = merge_values(key_node, value_node, existing_value_node)
            merged_dict[key] = (key_node, merged_value_node)

    return list(merged_dict.values())

