def deep_merge_nodes(nodes):
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            if isinstance(merged[key], ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                merged_value = deep_merge_nodes(merged[key].value + value_node.value)
                merged[key] = ruamel.yaml.nodes.MappingNode(tag=merged[key].tag, value=merged_value)
            else:
                merged[key] = value_node
        else:
            merged[key] = value_node

    return [(ruamel.yaml.nodes.ScalarNode(tag=key.tag, value=key), value) for key, value in merged.items()]

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(key, value, merged_dict):
        if key in merged_dict:
            if isinstance(value, MappingNode) and isinstance(merged_dict[key], MappingNode):
                merged_value = {}
                merge_values(value, merged_value, dict(merged_dict[key].value))
                merged_dict[key].value = list(merged_value.items())
            else:
                merged_dict[key] = value
        else:
            if isinstance(value, MappingNode):
                merged_dict[key] = MappingNode(tag=value.tag, value=dict(value.value))
            else:
                merged_dict[key] = value

    merged_dict = {}
    for key_node, value_node in nodes:
        if not isinstance(key_node, ScalarNode):
            raise ValueError("Key node must be a ScalarNode.")
        key = key_node.value
        merge_values(key, value_node, merged_dict)

    return [(ScalarNode(tag=key_node.tag, value=key), value) for key, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def merge_values(key, value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            merged_value = value1.value.copy()
            for k, v in value2.value:
                merged_key = k.value if isinstance(k, ScalarNode) else k
                merged_value = [item for item in merged_value if item[0] != k] + [(k, v)]
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            return value2

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value if isinstance(key_node, ScalarNode) else key_node
        if key in merged_dict:
            merged_dict[key] = merge_values(key_node, merged_dict[key], value_node)
        else:
            merged_dict[key] = value_node

    return [(ScalarNode(tag=key_node.tag, value=key), value) for key, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    def merge_values(key, value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            # Merge the two MappingNodes
            merged_value = value1.value.copy()
            for k2, v2 in value2.value:
                found = False
                for i, (k1, v1) in enumerate(merged_value):
                    if k1 == k2:
                        merged_value[i] = (k2, merge_values(k2, v1, v2))
                        found = True
                        break
                if not found:
                    merged_value.append((k2, v2))
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            # Last value wins for non-MappingNode values
            return value2

    merged_dict = {}
    for key, value in nodes:
        if key not in merged_dict:
            merged_dict[key] = value
        else:
            merged_dict[key] = merge_values(key, merged_dict[key], value)

    return [(key, value) for key, value in merged_dict.items()]

def deep_merge_nodes(nodes):
    from collections import defaultdict

    merged_dict = defaultdict(list)

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, ruamel.yaml.nodes.MappingNode):
            # If the value is a MappingNode, we need to merge it deeper
            if key not in merged_dict:
                merged_dict[key] = (key_node, value_node)
            else:
                _, existing_value_node = merged_dict[key]
                existing_value_dict = dict(existing_value_node.value)
                new_value_dict = dict(value_node.value)
                for k, v in new_value_dict.items():
                    existing_value_dict[k] = v
                existing_value_node.value = list(existing_value_dict.items())
        else:
            # For other types, we just overwrite with the last occurrence
            merged_dict[key] = (key_node, value_node)

    return list(merged_dict.values())

