def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import borgmatic.commands.borgmatic
        import argparse

        def generate_completion(parser, parent_commands=''):
            commands = []
            if parent_commands:
                command = parent_commands.split(' ')[-1]
                commands.append(f"_{command}_() {{")
                commands.append(f"    local cur prev words cword")
                commands.append("    _init_completion || return")
                commands.append(f"    _arguments ':command:->{command}'")
                commands.append(f"    case ${{cur}} in")
                for action in parser._actions:
                    if isinstance(action, argparse._SubParsersAction):
                        commands.append(f"        * )")
                        for choice in action.choices:
                            commands.append(f"            _arguments -C : :'{choice}' '{choice}:_'")
                        commands.append(f"            ;;")
                commands.append(f"    esac")
                commands.append(f"}}")

            for action in parser._actions:
                if isinstance(action, argparse._SubParsersAction):
                    for choice, subparser in action.choices.items():
                        subcommands = generate_completion(subparser, f"{parent_commands} {choice}")
                        commands.extend(subcommands)

            return commands

        main_parser = borgmatic.commands.borgmatic.create_parser()
        completion_script = ["#compdef borgmatic"]
        completion_script.extend(generate_completion(main_parser))
        completion_script.append(f"_borgmatic() {{")
        completion_script.append(f"    _dispatch 'borgmatic' && ret=0 || ret=1")
        completion_script.append(f"}}")
        completion_script.append(f"compdef _borgmatic borgmatic")
        return '\n'.join(completion_script)

    except ImportError:
        return "# Unable to generate bash completion due to missing borgmatic package."
    except Exception as e:
        return f"# Error generating bash completion: {str(e)}"

