def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    try:
        if not isinstance(response, list):
            raise ValueError("Response must be a list.")
        if not isinstance(max_results, int) or max_results <= 0:
            raise ValueError("Max results must be a positive integer.")

        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]

    except Exception as e:
        yield from ()  # Return an empty generator if an error occurs

def paging(response, max_results):
    if not isinstance(response, list):
        raise ValueError("Response must be a list.")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("Max results must be a positive integer.")

    start = 0
    while start < len(response):
        end = start + max_results
        yield response[start:end]
        start = end

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip().upper()
    try:
        if size.endswith('K'):
            return int(size[:-1]) * 1000
        elif size.endswith('M'):
            return int(size[:-1]) * 1000000
        elif size.endswith('G'):
            return int(size[:-1]) * 1000000000
        elif size.endswith('T'):
            return int(size[:-1]) * 1000000000000
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size format. Use a format like '500K', '1M', '1G', '1T' or just a number.")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    try:
        if size[-1].isdigit():
            return int(size)
        value = int(size[:-1])
        unit = size[-1].upper()
        if unit == 'K':
            return value * 1000
        elif unit == 'M':
            return value * 1000**2
        elif unit == 'G':
            return value * 1000**3
        elif unit == 'T':
            return value * 1000**4
        else:
            raise ValueError(f"Unknown unit: {unit}")
    except ValueError as e:
        raise ValueError(f"Invalid size format: {size}") from e

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    if not isinstance(dicts, (list, tuple)):
        raise ValueError("Input must be a list or tuple of dictionaries.")
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("Each element in the iterable must be a dictionary.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All values in the dictionaries must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

