def get_repo_archive(url: str, destination_path: Path) -> Path:
    import requests
    import tarfile
    import os

    if not url.endswith('.tar.gz'):
        raise ValueError("The provided URL must point to a .tar.gz file.")

    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to download the archive from {url}: {e}")

    try:
        with tarfile.open(fileobj=response.raw, mode='r:gz') as tar:
            tar.extractall(path=destination_path)
    except tarfile.TarError as e:
        raise Exception(f"Failed to extract the archive: {e}")

    return destination_path / os.path.splitext(os.path.basename(url))[0]

