    import re
    if platform == 'this':
        platform = 1 if re.match(r'posix|linux|darwin', re.sub(r'(_|\d.*)', '', str(platform).lower())) else 0
    if platform == 1:
        pattern = r'(?:(?P<quote>"|\'|)(?P<arg>[^"\']*(?:(?P=quote)[^"\']*)*)(?P=quote)|(?P<unquoted>[^\s]+)'
    elif platform == 0:
