        arg = match.group('arg') or match.group('unquoted')
        if quoted:
            arg = re.sub(r'(?<!\\)' + re.escape(quoted), '', arg)
        return arg

    try:
        return [parse_args(m) for m in re.finditer(pattern, s)]
    except TypeError:
        raise ValueError("Input string must be of type str.")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    def split_posix(input_str):
        # POSIX shell-like syntax
        return re.findall(r'''(?u)(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\\.)|(\S+))''', input_str)

    def split_windows(input_str):
        # Windows CMD-like syntax
        return re.findall(r'''(?u)(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\\.)|(\S+))''', input_str)

    try:
        if platform == 'this':
            platform = 1 if sys.platform != 'win32' else 0

        if platform == 1:
            result = split_posix(s)
        elif platform == 0:
            result = split_windows(s)
        else:
            raise ValueError("Unsupported platform value. Use 'this', 0, or 1.")

        return [item[0] or item[1] or item[2] or item[3] for item in result if any(item)]
    except Exception as e:
        raise ValueError(f"Error splitting string: {e}")

