        ignored_files = set()
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) > 2:
                # Add the file name to the set to avoid duplicates
                ignored_files.add(parts[2])

        # Sort the list of ignored files
        sorted_ignored_files = sorted(ignored_files)

        # Join the sorted list into a single string separated by commas
        return ','.join(sorted_ignored_files)

    except subprocess.CalledProcessError as e:
        # Handle the case where the git command fails
        return f"Error: {e.stderr.strip()}"
    except Exception as e:
        # Handle any other exceptions
        return f"An error occurred: {str(e)}"

