def is_local(host):
    try:
        # Resolve the hostname to an IP address
        ip_address = socket.gethostbyname(host)
        # Check if the IP address is 127.0.0.1 or ::1 (IPv6 loopback)
        return ip_address in ('127.0.0.1', '::1')
    except socket.error:
        # If there's an error resolving the hostname, assume it's not localhost
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        raise ValueError("Host must be a string")

    try:
        # Get the list of all local addresses
        local_addresses = socket.getaddrinfo(socket.gethostname(), None)
        local_ips = {ip[4][0] for ip in local_addresses if ip[4][0]}

        # Include 'localhost' and '127.0.0.1' explicitly
        local_ips.update(['localhost', '127.0.0.1'])

        # Resolve the given host to an IP address
        resolved_host = socket.getaddrinfo(host, None)
        resolved_ips = {ip[4][0] for ip in resolved_host if ip[4][0]}

        # Check if any of the resolved IPs match the local IPs
        return not resolved_ips.isdisjoint(local_ips)
    except socket.gaierror:
        # If the host cannot be resolved, assume it's not local
        return False

