def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    import os
    import sys
    import importlib

    if not callable(func):
        raise ValueError("func must be a callable function")

    # Construct the command to run the function
    module_name = func.__module__
    function_name = func.__name__
    if module_name == '__main__':
        raise ValueError("func must be in an importable module")

    if extra_env is None:
        extra_env = {}

    # Prepare environment for subprocess
    env = os.environ.copy()
    env.update(extra_env)

    # Serialize the function call
    function_call = f'{module_name}.{function_name}({" ".join(args)})'
    command = [sys.executable, '-c', f'from {module_name} import {function_name}; {function_call}']

    try:
        result = subprocess.run(command, env=env, timeout=timeout, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.TimeoutExpired:
        raise TimeoutError(f"The subprocess did not complete within the specified timeout of {timeout} seconds.")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"The subprocess failed with return code {e.returncode}\nOutput:\n{e.output}\nError:\n{e.stderr}")
    except Exception as e:
        raise Exception(f"An error occurred while running the subprocess: {e}")

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """Run a function in a sub-process."""
    import subprocess
    import os
    import importlib

    if not callable(func):
        raise ValueError("The provided func must be a callable function.")

    # Get the function's module and name
    func_module = func.__module__
    func_name = func.__name__

    # Check if the function's module can be imported
    try:
        importlib.import_module(func_module)
    except ImportError:
        raise ImportError(f"Module '{func_module}' cannot be imported.")

    # Prepare the environment for the subprocess
    env = os.environ.copy()
    if extra_env is not None:
        if not isinstance(extra_env, dict):
            raise ValueError("extra_env must be a dictionary.")
        env.update(extra_env)

    # Prepare the command to run the function in the subprocess
    cmd = ['python', '-c', f"import {func_module}; {func_module}.{func_name}({', '.join(repr(arg) for arg in args)})"]

    try:
        result = subprocess.run(cmd, env=env, timeout=timeout, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.TimeoutExpired:
        raise TimeoutError(f"Command '{cmd}' timed out after {timeout} seconds.")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command '{cmd}' returned a non-zero exit code: {e.returncode}\nOutput:\n{e.output}\nError:\n{e.stderr}")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    parts = matcher.split(':')
    if len(parts) == 1:
        name = parts[0]
        default_value = None
    elif len(parts) == 2:
        name, default_value = parts
    else:
        raise ValueError("Matcher should be in the format 'NAME' or 'NAME:DEFAULT_VALUE'")

    value = os.getenv(name)
    if value is None:
        if default_value is None:
            raise EnvironmentError(f"Environment variable '{name}' is not defined and no default value is provided.")
        return default_value
    return value

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, *default = matcher.split('=', 1)
        value = os.getenv(name)
        if value is None:
            if not default:
                raise ValueError(f"Environment variable '{name}' is not defined and no default value is provided.")
            value = default[0]
        return value
    except Exception as e:
        raise RuntimeError(f"Error resolving environment variable: {str(e)}")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")

    try:
        parsed_url = urllib.parse.urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Invalid URL: {e}")

    if not parsed_url.scheme:
        raise ValueError("URL must include a scheme (http or https)")

    use_ssl = parsed_url.scheme == 'https'
    netloc = parsed_url.netloc
    path = parsed_url.path.strip('/')

    if not path:
        raise ValueError("URL must include a path to an image")

    image_id = path.split('/')[-1]

    if not image_id:
        raise ValueError("Unable to determine image_id from URL")

    return image_id, netloc, use_ssl

