def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings.")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string or None.")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean.")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary or None.")

    full_command = commands + args
    try:
        result = subprocess.run(
            full_command,
            cwd=cwd,
            capture_output=verbose or hide_stderr,
            text=True,
            env=env,
            check=True
        )
        if verbose:
            print("Command output:\n", result.stdout)
        return result.stdout
    except subprocess.CalledProcessError as e:
        error_message = f"Command {' '.join(full_command)} failed with return code {e.returncode}"
        if not hide_stderr:
            error_message += f":\n{e.stderr}"
        raise RuntimeError(error_message) from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("The commands list cannot be empty.")
    if not isinstance(commands, list):
        raise TypeError("Commands must be provided as a list.")
    if not isinstance(args, list):
        raise TypeError("Arguments must be provided as a list.")

    try:
        command = commands + args
        if verbose:
            print(f"Running command: {' '.join(command)}")

        with subprocess.Popen(
            command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, errors = process.communicate()

        if process.returncode != 0:
            if verbose or not hide_stderr:
                print(f"Error: {errors}")
            raise subprocess.CalledProcessError(process.returncode, command, output, errors)

        return output

    except FileNotFoundError as e:
        raise FileNotFoundError(f"One of the commands was not found: {e}")
    except subprocess.SubprocessError as e:
        raise subprocess.SubprocessError(f"An error occurred while running the command: {e}")
