            raise ValueError("Commands must be a list of strings.")
        if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
            raise ValueError("Arguments must be a list of strings.")

        full_command = commands + args
        if verbose:
            print(f"Running command: {' '.join(full_command)} in directory: {cwd}")

        stderr = subprocess.DEVNULL if hide_stderr else None

        result = subprocess.run(
            full_command,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr
        )

        if verbose:
            print("Command output:", result.stdout)
            if result.stderr:
                print("Command error:", result.stderr)

        result.check_returncode()  # Raises CalledProcessError if return code is not 0
        return result.stdout

    except subprocess.CalledProcessError as e:
        print(f"Command failed with return code {e.returncode}")
        if verbose:
            print("Failed command output:", e.output)
            print("Failed command error:", e.stderr)
        raise
