def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    # Find all nodes that are not children (i.e., have no incoming prop edges)
    for s, p, o in graph:
        if p == prop:
            roots.add(o)

    for s, p, o in graph:
        if p == prop:
            if s in roots:
                roots.remove(s)

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    try:
        # Find all nodes that are not children in any triple with the given property
        for s, p, o in graph:
            if p == prop:
                roots.add(o)
                if o in roots:
                    roots.remove(o)

        # Add any node that is not a parent in any triple with the given property
        for s, p, o in graph:
            if p == prop and s not in roots:
                roots.add(s)

    except Exception as e:
        raise ValueError(f"An error occurred while processing the graph: {e}")

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    if not isinstance(graph, rdflib.Graph) or not isinstance(prop, rdflib.URIRef):
        raise ValueError("Invalid input types: graph must be an rdflib.Graph and prop must be an rdflib.URIRef")

    try:
        nodes_with_parents = set()
        for _, parent in graph.subject_objects(prop):
            nodes_with_parents.add(parent)

        for node in graph.subjects():
            if node not in nodes_with_parents:
                roots.add(node)

    except Exception as e:
        raise RuntimeError(f"An error occurred while finding roots: {e}")

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        # Find all nodes that have no incoming edges with the given property
        for subject in graph.subjects():
            if not list(graph.predicates(subject, prop)):
                roots.add(subject)
        # Remove nodes that are also objects of the given property
        for _, _, obj in graph.triples((None, prop, None)):
            if obj in roots:
                roots.remove(obj)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    if not isinstance(graph, rdflib.Graph):
        raise ValueError("The graph must be an instance of rdflib.Graph.")
    if not isinstance(prop, rdflib.URIRef):
        raise ValueError("The prop must be an instance of rdflib.URIRef.")

    # Initialize a set to keep track of nodes that have parents
    has_parent = set()

    # Traverse the graph to find all nodes and their parents
    for subject, predicate, obj in graph.triples((None, prop, None)):
        if predicate == prop:
            has_parent.add(subject)

    # Roots are nodes that are not in the has_parent set
    for subject, _, _ in graph.triples((None, prop, None)):
        if subject not in has_parent:
            roots.add(subject)

    return roots

