def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    def parse_config_file(filename):
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
            return config
        except (FileNotFoundError, PermissionError) as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error accessing file: {e}", args=(), exc_info=True))
            return None
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error decoding JSON: {e}", args=(), exc_info=True))
            return None

    def resolve_environment_variables(config):
        if not resolve_env:
            return config
        for key, value in config.items():
            if isinstance(value, str) and value.startswith('$'):
                env_var_name = value[1:]
                env_var_value = os.getenv(env_var_name)
                if env_var_value is None:
                    log_records.append(logging.LogRecord(name='config_loader', level=logging.WARNING, pathname='environment', lineno=0, msg=f"Environment variable '{env_var_name}' not found", args=(), exc_info=False))
                config[key] = env_var_value
            elif isinstance(value, dict):
                config[key] = resolve_environment_variables(value)
        return config

    for filename in config_filenames:
        config = parse_config_file(filename)
        if config is not None:
            config = resolve_environment_variables(config)
            config.update(overrides)  # Apply overrides
            config_dict[filename] = config

    return config_dict, log_records

