        errors.append(f"Candidate does not provide the required interface {iface}")

    # Check for required methods and their signatures
    required_methods = iface.names(all=True, inherited=True)
    for method_name in required_methods:
        if method_name not in dir(candidate):
            errors.append(f"Candidate is missing required method: {method_name}")
            continue

        method = getattr(candidate, method_name)
        if not callable(method):
            errors.append(f"Required method {method_name} is not callable")
            continue

