        if vtype:
            iface_method = iface.get(method_name)
            if iface_method:
                iface_signature = inspect.signature(iface_method)
                candidate_signature = inspect.signature(method)
                if candidate_signature != iface_signature:
                    errors.append(f"Signature mismatch for method {method_name}: expected {iface_signature}, got {candidate_signature}")

    # Check for required attributes
    required_attributes = iface.names(all=True, inherited=True) - set(dir(candidate))
    for attr_name in required_attributes:
        errors.append(f"Candidate is missing required attribute: {attr_name}")

    if errors:
        if len(errors) == 1:
