def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    inside_code_block = False
    result_text = []
    i = 0
    while i < len(text):
        if text[i:i+3] == '```':
            inside_code_block = not inside_code_block
            result_text.append(text[i:i+3])
            i += 3
        elif text[i] == '#' and not inside_code_block:
            j = i + 1
            while j < len(text) and text[j].isalnum():
                j += 1
            tag = text[i:j]
            if len(tag) > 1:  # Ensure it's a valid tag, not just a single '#'
                tags.add(tag)
                if replacer:
                    replacement = replacer(tag)
                    result_text.append(replacement)
                    i += len(tag)
                else:
                    result_text.append(tag)
                    i += len(tag)
            else:
                result_text.append(text[i])
                i += 1
        else:
            result_text.append(text[i])
            i += 1
    return tags, ''.join(result_text)

