def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from xml.etree import ElementTree as ET

    if not isinstance(handle, str) or not handle:
        raise ValueError("Handle must be a non-empty string")

    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger", params={"resource": f"acct:{handle}"})
        response.raise_for_status()  # Raise an error for bad responses
    except requests.RequestException as e:
        raise Exception(f"Error retrieving webfinger document: {e}")

    try:
        root = ET.fromstring(response.content)
    except ET.ParseError as e:
        raise Exception(f"Error parsing webfinger document: {e}")

    result = {}
    for elem in root.iter():
        if elem.tag.endswith('}subject'):
            result['subject'] = elem.text
        elif elem.tag.endswith('}alias'):
            result['alias'] = elem.text
        elif elem.tag.endswith('}link'):
            link_type = elem.attrib.get('rel')
            href = elem.attrib.get('href')
            if link_type and href:
                if link_type not in result:
                    result[link_type] = []
                result[link_type].append(href)

    return result

