    if not isinstance(include_directive, dict):
        raise ValueError("include directive must be a dictionary")

    for group_name, group_items in include_directive.items():
        if not isinstance(group_items, list):
            raise ValueError(f"Items for group {group_name} must be a list")
        for item in group_items:
            if item not in parser_dict:
                raise ValueError(f"Item {item} in group {group_name} not found in parser_dict")
