def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings.")

    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")

    stripped_path = path[len(root):]
    # Remove any leading slash from the stripped path if the original path had a slash after the root
    if root and path[len(root):len(root)+1] == '/':
        stripped_path = stripped_path[1:]

    return stripped_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path or not root:
        raise ValueError("Both path and root must be non-empty strings.")
    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")
    stripped_path = path[len(root):]
    # Ensure we don't return a leading slash if root doesn't end with one but path does
    if root.endswith('/') and not stripped_path.startswith('/'):
        return stripped_path
    elif not root.endswith('/') and stripped_path.startswith('/'):
        return stripped_path[1:]
    return stripped_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings.")

    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")

    stripped_path = path[len(root):]
    # Ensure we handle the case where root is the entire path
    if not stripped_path and path != root:
        raise ValueError("Path is a prefix of root but not equal to root.")

    # Remove any leading slash from the stripped path
    if stripped_path.startswith('/'):
        stripped_path = stripped_path[1:]

    return stripped_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings.")
    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")
    stripped_path = path[len(root):]
    # Remove any leading slashes from the stripped path
    stripped_path = stripped_path.lstrip('/')
    return stripped_path
